import { GeneralProblem, d } from './utils';

type Entry = [string, string, string, string, string, string];
type DualEntry = [string, string, string, string, string, string, string];

const toProblems = (entries: Entry[]): GeneralProblem[] => entries.map(([question, answer, a, b, c, hint]) => ({
  question,
  answer,
  options: d(answer, a, b, c),
  hint,
}));

const toDualProblems = (entries: DualEntry[]): GeneralProblem[] => toProblems(entries.flatMap(([q1, q2, answer, a, b, c, hint]) => ([
  [q1, answer, a, b, c, hint],
  [q2, answer, a, b, c, hint],
])));

